// Nhan dien va format thay doi theo dung 6 truong hop da xac nhan qua payload that (05/09/2026).
// Node nay tra ve NHIEU item (1 item = 1 thay doi can thong bao) - khong can node Split Out rieng.
const body = $json;
const historyItems = body.history_items || [];
const taskId = body.task_id;

function extractPlainTextFromDelta(raw) {
  try {
    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (parsed && Array.isArray(parsed.ops)) {
      return parsed.ops.map(op => (typeof op.insert === 'string' ? op.insert : '')).join('').trim();
    }
  } catch (e) { }
  return typeof raw === 'string' ? raw : '';
}

const results = [];
for (const h of historyItems) {
  const changedBy = h.user?.username || 'không rõ';
  const dateStr = h.date ? new Date(Number(h.date)).toLocaleString('vi-VN') : '';
  let label = null, valueText = null;

  if (h.field === 'comment') {
    label = 'Comment mới';
    valueText = 'Có comment mới trên task';
  } else if (h.field === 'content') {
    label = 'Mô tả';
    const text = extractPlainTextFromDelta(h.after);
    valueText = text.length > 200 ? text.slice(0, 200) + '…' : (text || '(trống)');
  } else if (h.field === 'custom_field' && h.custom_field) {
    // Doc TEN field truc tiep tu payload - khong can hardcode map, tu dong ho tro moi custom field
    label = h.custom_field.name;
    valueText = (h.after && typeof h.after === 'object') ? JSON.stringify(h.after) : String(h.after ?? '(trống)');
  } else if (h.field === 'assignee_add') {
    label = 'Phụ trách (thêm)';
    valueText = h.after?.username || h.after?.email || 'không rõ';
  } else if (h.field === 'name') {
    label = 'Tên task';
    valueText = h.after;
  } else if (h.field === 'status') {
    label = 'Trạng thái';
    const before = (h.before && typeof h.before === 'object') ? h.before.status : h.before;
    const after = (h.after && typeof h.after === 'object') ? h.after.status : h.after;
    valueText = `${before || '—'} ➜ ${after || '—'}`;
  } else {
    continue; // field khong theo doi (due_date, priority, assignee_rem...) - bo qua
  }

  results.push({ json: { taskId, label, valueText, changedBy, dateStr } });
}

if (results.length === 0) {
  return [{ json: { taskId, skip: true } }];
}
return results;

const change = $('Nhận Diện & Format Thay Đổi').item.json;
const admin = $('Lay Admin Chat ID (F2)').first().json;
const task = $json; // { id, name, url } tu Lay Thong Tin Task (co the rong neu task chua sync)

const text = `🔄 <b>Thông báo CẬP NHẬT Task</b>\n\n` +
  `🔧 Thay đổi:\n` +
  `📝 Trường "${change.label}" được cập nhật bởi ${change.changedBy}\n` +
  `✅ Giá trị mới: ${change.valueText}\n\n` +
  `📦 Thông tin:\n` +
  `🆔 ID: ${task.id || change.taskId}\n` +
  `📌 Tên: ${task.name || '—'}\n` +
  `🔗 Link: ${task.url || '—'}\n` +
  (change.dateStr ? `🕒 Cập nhật lúc: ${change.dateStr}\n` : '') +
  `#task_updated`;

return [{ json: { chatId: admin.admin_chat_id, text } }];
